-- The previous migration wrote the Thai names as literals, and a migrate connection that was not utf8mb4 stored them
-- garbled (UTF-8 read as TIS-620 or latin1, so every Thai letter turned into "เธ…" or "à¸…"). Rewrite them from UTF-8 bytes so the result
-- does not depend on the connection's character set, touching only rows that are still garbled, and move any account
-- that picked a garbled name along with it.
UPDATE `users` SET `healthCenter` = CONVERT(X'50435520E0B8A3E0B89E2EE0B8A7E0B8B2E0B8A3E0B8B4E0B88AE0B8A0E0B8B9E0B8A1E0B8B4' USING utf8mb4) WHERE `healthCenter` = (SELECT `name` FROM `health_centers` WHERE `id` = '01HC0000000000000000000001' AND (INSTR(`name`, CONVERT(X'E0B980E0B898' USING utf8mb4)) > 0 OR INSTR(`name`, CONVERT(X'C3A0C2B8' USING utf8mb4)) > 0));
UPDATE `health_centers` SET `name` = CONVERT(X'50435520E0B8A3E0B89E2EE0B8A7E0B8B2E0B8A3E0B8B4E0B88AE0B8A0E0B8B9E0B8A1E0B8B4' USING utf8mb4) WHERE `id` = '01HC0000000000000000000001' AND (INSTR(`name`, CONVERT(X'E0B980E0B898' USING utf8mb4)) > 0 OR INSTR(`name`, CONVERT(X'C3A0C2B8' USING utf8mb4)) > 0);
